using System.Windows.Input;
namespace DiskLens;
public partial class MainVm {
 public string[] DuplicateCheckModes{get;}=["Quick (up to 5,000 files)","Full (all candidates)"];string duplicateCheckMode="Quick (up to 5,000 files)";public string DuplicateCheckMode{get=>duplicateCheckMode;set{duplicateCheckMode=value;Notify();}}
 public string[] DuplicateCategories{get;}=["All","Documents","Images","Video","Archives","Installers","Code","Applications","Other"];public string DuplicateCategory{get;set;}="All";
 public InvestigationPreset[] InvestigationPresets{get;}=[new("changes","What changed","History"),new("recent","Recent large files","TrendingUp"),new("old","Old large files","Clock3"),new("installers","Installer files","Download"),new("archives","Archives and images","Archive"),new("developer","Developer clutter","FileCode2"),new("duplicates","Duplicate files","Hash"),new("health","Storage health","ShieldAlert")];
 public ObservableCollection<Entry> InvestigationRows{get;}=[];
