 public bool IsInvestigationLoading{get;private set;}
 public string ComparisonContext{get;private set;}="";
 public string InvestigationStatus{get;private set;}="Select a completed scan";
 public string InvestigationDescription=>SelectedInvestigation.Id switch {"changes"=>"Added, grown, shrunk and removed files between completed scans of the same volume.","recent"=>"Files of at least 1 MB changed in the last 30 days, largest first.","old"=>"Files of at least 1 MB not modified for over 180 days, largest first.","installers"=>"Installer packages and setup-style executables. Review before cleanup.","archives"=>"Archive and image files, excluding installer packages.","developer"=>"Dependency folders, build outputs, cache and temporary paths. A match does not prove a file is unused.","duplicates"=>"Quick checks up to 5,000 candidates, smallest first; Full checks all. Both verify full SHA-256. Hard links are excluded and suggested keepers are protected.",_=>"Skipped scan paths and read-only Windows storage signals. Offline snapshots cannot provide live health."};
 InvestigationPreset? investigation;long investigationRevision;CancellationTokenSource? investigationQuery;
 public InvestigationPreset SelectedInvestigation{get=>investigation??InvestigationPresets[0];set{investigation=value;Selected=null;SelectedFiles=[];Notify();Notify(nameof(InvestigationDescription));_=LoadInvestigation();}}
 int activeTab;public int ActiveTab{get=>activeTab;set{activeTab=value;Selected=null;SelectedFiles=[];Notify();if(value==2)_=LoadInvestigation();else {investigationQuery?.Cancel();IsInvestigationLoading=false;Notify(nameof(IsInvestigationLoading));}if(value==3)_=LoadInsights();}}
 public ObservableCollection<Entry> ActiveRows=>ActiveTab==2?InvestigationRows:Rows;
 public ICommand RefreshInvestigation=>new Command(async _=>await LoadInvestigation(),()=>!Busy&&scan!=null);
 public ICommand QuickDuplicateCheck=>new Command(async _=>{DuplicateCheckMode=DuplicateCheckModes[0];await FindDuplicates();},()=>!Busy&&scan!=null);
 public ICommand FullDuplicateCheck=>new Command(async _=>{DuplicateCheckMode=DuplicateCheckModes[1];await FindDuplicates();},()=>!Busy&&scan!=null);
 public ICommand CheckInvestigation=>new Command(async _=>{if(SelectedInvestigation.Id=="duplicates")await FindDuplicates();else if(SelectedInvestigation.Id=="health")await CheckHealth();else await LoadInvestigation();},()=>!Busy&&scan!=null);
 public async Task LoadInvestigation(){if(ActiveTab!=2)return;var revision=++investigationRevision;investigationQuery?.Cancel();var cancellation=new CancellationTokenSource();investigationQuery=cancellation;var current=scan;var preset=SelectedInvestigation;IsInvestigationLoading=true;Notify(nameof(IsInvestigationLoading));ComparisonContext="";Notify(nameof(ComparisonContext));InvestigationRows.Clear();InvestigationCards.Clear();InvestigationStatus="Loading completed scan…";Notify(nameof(InvestigationStatus));try{
 if(current==null){InvestigationStatus="Select or create a completed scan first.";return;}
 if(preset.Id=="duplicates"){InvestigationStatus="Choose Quick check (up to 5,000 candidates) or Full check (all filtered candidates). Filters below apply.";return;}
 List<Entry> result;ChangeSummary? summary=null;
 if(preset.Id=="changes"){var saved=await Task.Run(()=>store.History().Where(s=>File.Exists(store.PathFor(s))).ToArray(),cancellation.Token);if(revision!=investigationRevision||current!=scan)return;SyncSavedHistory(saved);var previous=ComparisonSelection.Previous(current,saved);ComparisonDiagnostics.Write(store,current,saved,previous);if(previous==null){var count=saved.Count(s=>ComparisonSelection.Compatible(current,s));InvestigationStatus=store.HistoryWarning.Length>0?"Saved snapshots could not be loaded: "+store.HistoryWarning:count>1?"The selected scan is the earliest saved scan. Select a later scan in Insights / History to compare it with an earlier scan.":"No earlier compatible snapshot was found. Open Insights / History to inspect the saved scans.";return;}ComparisonContext=$"Previous: {DateTime.Parse(previous.Date).ToLocalTime():g} → Current: {DateTime.Parse(current.Date).ToLocalTime():g} • {saved.Count(s=>ComparisonSelection.Compatible(current,s))} compatible completed scans";Notify(nameof(ComparisonContext));InvestigationStatus="Comparing completed indexes…";Notify(nameof(InvestigationStatus));var data=await Task.Run(()=>InvestigationStore.Changes(store,current,previous,cancellation.Token));result=data.Rows;summary=data.Summary;}
 else if(preset.Id=="health")result=await Task.Run(()=>store.Issues(current));
 else result=await Task.Run(()=>InvestigationStore.Files(store,current,preset.Label,Query,Minimum,Maximum,0,cancellation.Token));
 if(revision!=investigationRevision||current!=scan)return;foreach(var row in result)InvestigationRows.Add(row);
 if(summary!=null){InvestigationCards.Add(new("Added",Entry.Format(summary.Added)));InvestigationCards.Add(new("Growth",Entry.Format(summary.Grown)));InvestigationCards.Add(new("Freed or removed",Entry.Format(summary.Shrunk+summary.Removed),"Logical bytes; exclusions and inaccessible paths can affect comparisons"));InvestigationStatus=$"{summary.Count:N0} changed items • showing up to 1,000, ordered by absolute difference";}
 else {InvestigationCards.Add(new("Displayed items",result.Count.ToString("N0")));InvestigationCards.Add(new("Displayed size",Entry.Format(result.Sum(e=>e.Size))));InvestigationCards.Add(new("Largest item",Entry.Format(result.FirstOrDefault()?.Size??0)));InvestigationStatus=preset.Id=="health"?$"{current.Issues:N0} recorded skipped paths • showing up to 500. Choose Run health check for live Windows health.":"Showing up to 500 matching files from the completed scan, largest first. Use Search to page through the full index.";}
 }catch(OperationCanceledException){}catch(Exception e){if(revision==investigationRevision)InvestigationStatus="Investigation unavailable: "+e.Message;}finally{if(revision==investigationRevision){IsInvestigationLoading=false;Notify(nameof(IsInvestigationLoading));Notify(nameof(InvestigationStatus));}cancellation.Dispose();if(investigationQuery==cancellation)investigationQuery=null;}}
 async Task CheckHealth(){investigationQuery?.Cancel();IsInvestigationLoading=false;Notify(nameof(IsInvestigationLoading));var revision=++investigationRevision;Busy=true;operation=new();try{var result=await NativeWorkers.Health(operation.Token);if(revision!=investigationRevision||SelectedInvestigation.Id!="health")return;InvestigationRows.Clear();foreach(var row in result)InvestigationRows.Add(row);if(scan!=null)foreach(var row in store.Issues(scan))InvestigationRows.Add(row);InvestigationStatus="Live Windows drive signals and recent storage events, followed by recorded skipped paths. Blank telemetry means unavailable.";Notify(nameof(InvestigationStatus));}catch(OperationCanceledException){InvestigationStatus="Health check cancelled.";Notify(nameof(InvestigationStatus));}catch(Exception e){InvestigationStatus=e.Message;Notify(nameof(InvestigationStatus));}finally{Busy=false;operation.Dispose();operation=null;}}
}




